import android.app.Application
import android.net.Uri
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.ryen.sunnah_alhadi.domain.model.Sunnah
import com.ryen.sunnah_alhadi.domain.repository.ImageExportRepository
import com.ryen.sunnah_alhadi.util.Result
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import javax.inject.Inject

@HiltViewModel
class ImageExportViewModel @Inject constructor(
 application: Application,
 private val imageExportRepository: ImageExportRepository
) : AndroidViewModel(application) {

 private val _exportState = MutableStateFlow<ExportState>(ExportState.Idle)
 val exportState: StateFlow<ExportState> = _exportState.asStateFlow()

 fun exportSunnahAsImage(sunnah: Sunnah, action: ExportAction) {
 viewModelScope.launch {
 _exportState.value = ExportState.Loading

 val result = when (action) {
 ExportAction.SAVE -> imageExportRepository.saveSunnahAsImage(sunnah)
 ExportAction.SHARE -> imageExportRepository.shareSunnahAsImage(sunnah)
 }

 _exportState.value = when (result) {
 is Result.Success -> ExportState.Success(result.data as Uri?)
 is Result.Error -> ExportState.Error(result.message ?: "Unknown error occurred")
 }
 }
 }

 fun resetState() {
 _exportState.value = ExportState.Idle
 }
}

sealed class ExportState {
 object Idle : ExportState()
 object Loading : ExportState()
 data class Success(val uri: Uri?) : ExportState()
 data class Error(val message: String) : ExportState()
}

enum class ExportAction {
 SAVE,
 SHARE
