import android.content.Context
import android.net.Uri
import com.ryen.sunnah_alhadi.domain.model.Sunnah
import com.ryen.sunnah_alhadi.domain.repository.ImageExportRepository
import com.ryen.sunnah_alhadi.domain.useCase.ExportAction
import com.ryen.sunnah_alhadi.domain.useCase.ExportParams
import com.ryen.sunnah_alhadi.domain.useCase.ExportSunnahAsImageUseCase
import com.ryen.sunnah_alhadi.util.Result
import dagger.hilt.android.qualifiers.ApplicationContext
import javax.inject.Inject

class ImageExportRepositoryImpl @Inject constructor(
 @ApplicationContext private val context: Context,
 private val exportSunnahAsImageUseCase: ExportSunnahAsImageUseCase
) : ImageExportRepository {

 override suspend fun saveSunnahAsImage(sunnah: Sunnah): Result<Uri?> {
 val params = ExportParams(sunnah, ExportAction.SAVE)
 return when (val result = exportSunnahAsImageUseCase(params)) {
 is com.ryen.sunnah_alhadi.domain.useCase.ExportResult.Success -> Result.Success(result.uri)
 is com.ryen.sunnah_alhadi.domain.useCase.ExportResult.Error -> Result.Error(
 Exception(
 result.message
 ), result.message
 )
 }
 }

 override suspend fun shareSunnahAsImage(sunnah: Sunnah): Result<Unit> {
 val params = ExportParams(sunnah, ExportAction.SHARE)
 return when (val result = exportSunnahAsImageUseCase(params)) {
 is com.ryen.sunnah_alhadi.domain.useCase.ExportResult.Success -> Result.Success(Unit)
 is com.ryen.sunnah_alhadi.domain.useCase.ExportResult.Error -> Result.Error(
 Exception(
 result.message
 ), result.message
 )
 }
 }
}"},{"role":"assistant","content":[{"type":"text","text":"Now let me check the ExportSunnahAsImageUseCase to understand how the image export is currently implemented.









"}],"tool_calls":[{"id":"call_p1nhnute3","type":"function","function":{"name":"read_file","arguments":"{"relative_workspace_path":"app/src/main/java/com/ryen/sunnah_alhadi/domain/useCase/ExportSunnahAsImageUseCase.kt"}"}}]},{"role":"tool","name":"read_file","tool_call_id":"call_p1nhnute3","content":"package com.ryen.sunnah_alhadi.domain.useCase

import android.content.Context
import android.graphics.Bitmap
import androidx.compose.foundation.background
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.material3.MaterialTheme
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import com.ryen.sunnah_alhadi.domain.model.Sunnah
import com.ryen.sunnah_alhadi.presentation.components.SunnahFullCard
import com.ryen.sunnah_alhadi.util.ImageExportUtil

class ExportSunnahAsImageUseCase(
 private val context: Context
) : UseCase<ExportParams, ExportResult>() {

 override suspend fun execute(parameters: ExportParams): ExportResult {
 return try {
 // Create the composable content with 9:16 aspect ratio
 val width = 1080
 val height = 1920 // 9:16 aspect ratio

 val bitmap = ImageExportUtil.captureComposableAsBitmap(
 context = context,
 composable = {
 SunnahCardWithContainer(
 sunnah = parameters.sunnah,
 backgroundColor = Color.Black
 )
 },
 width = width,
 height = height
 )

 // Remove spaces from the title for filename
 val filename = parameters.sunnah.title.replace(" ", "")

 when (parameters.action) {
 ExportAction.SAVE -> {
 val uri = ImageExportUtil.saveBitmapLocally(context, bitmap, filename)
 if (uri != null) {
 ExportResult.Success(uri)
 } else {
 ExportResult.Error("Failed to save image or image already exists")
 }
 }
 ExportAction.SHARE -> {
 ImageExportUtil.shareBitmap(context, bitmap, filename)
 ExportResult.Success(null) // No URI needed for share action
 }
 }
 } catch (e: Exception) {
 ExportResult.Error(e.message ?: "Unknown error occurred")
 }
 }
}

@Composable
fun SunnahCardWithContainer(
 sunnah: Sunnah,
 backgroundColor: Color
) {
 Box(
 modifier = Modifier
 .fillMaxSize()
 .background(backgroundColor)
 ) {
 SunnahFullCard(
 sunnah = sunnah,
 modifier = Modifier.fillMaxSize()
 )
 }
}

data class ExportParams(
 val sunnah: Sunnah,
 val action: ExportAction
)

enum class ExportAction {
 SAVE,
 SHARE
}

sealed class ExportResult {
 data class Success(val uri: android.net.Uri?) : ExportResult()
 data class Error(val message: String) : ExportResult()
}"},{"role":"assistant","content":[{"type":"text","text":"Let me check the ImageExportUtil to understand the current implementation and see what needs to be added for better UX with status toasts.











