import android.content.Context
import android.content.Intent
import android.graphics.Bitmap
import android.graphics.Canvas
import android.graphics.Color
import android.net.Uri
import android.os.Build
import android.os.Environment
import android.widget.Toast
import androidx.compose.runtime.Composable
import androidx.compose.ui.graphics.toArgb
import androidx.compose.ui.platform.ComposeView
import androidx.core.content.FileProvider
import java.io.File
import java.io.FileOutputStream

object ImageExportUtil {

 /**
 * Convert a composable to a Bitmap with specified dimensions
 */
 fun captureComposableAsBitmap(
 context: Context,
 composable: @Composable () -> Unit,
 width: Int,
 height: Int
 ): Bitmap {
 val composeView = ComposeView(context)
 composeView.setContent(composable)

 // Measure and layout the composable
 composeView.measure(
 android.view.View.MeasureSpec.makeMeasureSpec(
 width,
 android.view.View.MeasureSpec.EXACTLY
 ),
 android.view.View.MeasureSpec.makeMeasureSpec(
 height,
 android.view.View.MeasureSpec.EXACTLY
 )
 )
 composeView.layout(0, 0, width, height)

 // Create bitmap and draw composable onto it
 val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
 val canvas = Canvas(bitmap)
 val backgroundColor = androidx.compose.ui.graphics.Color.Black
 canvas.drawColor(backgroundColor.toArgb())
 composeView.draw(canvas)

 return bitmap
 }

 /**
 * Save bitmap to local storage with specified filename
 */
 fun saveBitmapLocally(
 context: Context,
 bitmap: Bitmap,
 filename: String
 ): Uri? {
 return try {
 val imagesDir =
 File(context.getExternalFilesDir(Environment.DIRECTORY_PICTURES), "sunnah_cards")
 if (!imagesDir.exists()) {
 imagesDir.mkdirs()
 }

 val file = File(imagesDir, "$filename.png")
 if (file.exists()) {
 Toast.makeText(context, "Sunnah card already exists", Toast.LENGTH_SHORT).show()
 return null
 }

 FileOutputStream(file).use { out ->
 bitmap.compress(Bitmap.CompressFormat.PNG, 100, out)
 }

 Toast.makeText(context, "Sunnah card saved successfully", Toast.LENGTH_SHORT).show()

 // Get URI for the file
 FileProvider.getUriForFile(
 context,
 "${context.packageName}.fileprovider",
 file
 )
 } catch (e: Exception) {
 Toast.makeText(context, "Failed to save sunnah card: ${e.message}", Toast.LENGTH_LONG)
 .show()
 null
 }
 }

 /**
 * Share bitmap using Android's sharing intent
 */
 fun shareBitmap(
 context: Context,
 bitmap: Bitmap,
 filename: String
 ) {
 val uri = saveBitmapLocally(context, bitmap, filename) ?: return

 val shareIntent = Intent().apply {
 action = Intent.ACTION_SEND
 putExtra(Intent.EXTRA_STREAM, uri)
 type = "image/png"
 addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
 }

 context.startActivity(
 Intent.createChooser(shareIntent, "Share Sunnah Card")
 )
 }
}"},{"role":"assistant","content":[{"type":"text","text":"Now let me check the AndroidManifest.xml to ensure we have the proper permissions for saving and sharing images.







"}],"tool_calls":[{"id":"call_tt8j5tqhg","type":"function","function":{"name":"read_file","arguments":"{"relative_workspace_path":"app/src/main/AndroidManifest.xml"}"}}]},{"role":"tool","name":"read_file","tool_call_id":"call_tt8j5tqhg","content":"<?xml version="1.0" encoding="utf-8"?>
