```kotlin
package com.ryen.sunnah_alhadi.util

import android.content.Context
import android.content.Intent
import android.graphics.Bitmap
import android.graphics.Canvas
import android.net.Uri
import android.os.Environment
import androidx.compose.runtime.Composable
import androidx.compose.ui.platform.ComposeView
import androidx.core.content.FileProvider
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.io.File
import java.io.FileOutputStream

object ImageExportUtil {

 /**
 * Convert a composable to a Bitmap with specified dimensions
 */
 suspend fun captureComposableAsBitmap(
 context: Context,
 composable: @Composable () -> Unit,
 width: Int,
 height: Int
 ): Result<Bitmap> = withContext(Dispatchers.Main) {
 return@withContext try {
 val composeView = ComposeView(context)
 composeView.setContent(composable)

 // Measure and layout the composable
 composeView.measure(
 android.view.View.MeasureSpec.makeMeasureSpec(
 width,
 android.view.View.MeasureSpec.EXACTLY
 ),
 android.view.View.MeasureSpec.makeMeasureSpec(
 height,
 android.view.View.MeasureSpec.EXACTLY
 )
 )
 composeView.layout(0, 0, width, height)

 // Create bitmap and draw composable onto it
 val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
 val canvas = Canvas(bitmap)
 composeView.draw(canvas)

 Result.Success(bitmap)
 } catch (e: Exception) {
 Result.Error(e, e.message ?: "Failed to capture composable as bitmap")
 }
 }

 /**
 * Save bitmap to local storage with specified filename
 */
 suspend fun saveBitmapLocally(
 context: Context,
 bitmap: Bitmap,
 filename: String
 ): Result<Uri> = withContext(Dispatchers.IO) {
 return@withContext try {
 // Check permissions first
 if (!PermissionUtil.hasStoragePermission(context)) {
 return@withContext Result.Error(
 Exception("Storage permission not granted"),
 "Storage permission is required to save images"
 )
 }

 val imagesDir = context.getExternalFilesDir(Environment.DIRECTORY_PICTURES)?.let {
 File(it, "sunnah_cards")
 } ?: return@withContext Result.Error(
 Exception("Failed to access storage"),
 "Failed to access storage directory"
 )

 if (!imagesDir.exists()) {
 imagesDir.mkdirs()
 }

 val file = File(imagesDir, "$filename.png")
 if (file.exists()) {
 return@withContext Result.Error(
 Exception("File already exists"),
 "Sunnah card already exists"
 )
 }

 FileOutputStream(file).use { out ->
 bitmap.compress(Bitmap.CompressFormat.PNG, 100, out)
 }

 // Get URI for the file
 val uri = FileProvider.getUriForFile(
 context,
 "${context.packageName}.provider",
 file
 )

 Result.Success(uri)
 } catch (e: Exception) {
 Result.Error(e, "Failed to save sunnah card: ${e.message}")
 }
 }

 /**
 * Share bitmap using Android's sharing intent
 */
 fun shareBitmap(
 context: Context,
 uri: Uri
 ) {
 try {
 val shareIntent = Intent().apply {
 action = Intent.ACTION_SEND
 putExtra(Intent.EXTRA_STREAM, uri)
 type = "image/png"
 addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
 }

 context.startActivity(
 Intent.createChooser(shareIntent, "Share Sunnah Card")
 )
 } catch (e: Exception) {
 e.printStackTrace()
 }
 }
}
