object ImageExportUtil {

 /**
 * Convert a composable to a Bitmap with specified dimensions
 */
 suspend fun captureComposableAsBitmap(
 context: Context,
 composable: @Composable () -> Unit,
 width: Int,
 height: Int
 ): Result<Bitmap> = withContext(Dispatchers.Main) {
 return@withContext try {
 val composeView = ComposeView(context)
 composeView.setContent(composable)

 // Create a temporary parent view to attach the ComposeView
 val parentView = View.inflate(context, android.R.layout.simple_list_item_1, null) as ViewGroup
 parentView.addView(composeView)

 // Measure and layout the composable
 composeView.measure(
 View.MeasureSpec.makeMeasureSpec(width, View.MeasureSpec.EXACTLY),
 View.MeasureSpec.makeMeasureSpec(height, View.MeasureSpec.EXACTLY)
 )
 composeView.layout(0, 0, composeView.measuredWidth, composeView.measuredHeight)

 // Create bitmap and draw composable onto it
 val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
 val canvas = Canvas(bitmap)
 composeView.draw(canvas)

 // Clean up
 parentView.removeView(composeView)

 Result.Success(bitmap)
 } catch (e: Exception) {
 Result.Error(e, e.message ?: "Failed to capture composable as bitmap")
 }
 }

 /**
 * Save bitmap to local storage with specified filename
 */
 suspend fun saveBitmapLocally(
 context: Context,
 bitmap: Bitmap,
 filename: String
 ): Result<Uri> = withContext(Dispatchers.IO) {
 return@withContext try {
 // Check permissions first
 if (!PermissionUtil.hasStoragePermission(context)) {
 return@withContext Result.Error(
 Exception("Storage permission not granted"),
 "Storage permission is required to save images"
 )
 }

 val imagesDir = context.getExternalFilesDir(Environment.DIRECTORY_PICTURES)?.let {
 File(it, "sunnah_cards")
 } ?: return@withContext Result.Error(
 Exception("Failed to access storage"),
 "Failed to access storage directory"
 )

 if (!imagesDir.exists()) {
 imagesDir.mkdirs()
 }

 val file = File(imagesDir, "$filename.png")
 if (file.exists()) {
 return@withContext Result.Error(
 Exception("File already exists"),
