ess -> ExportResult.Success(uriResult.data)\n is Result.Error -> ExportResult.Error(uriResult.message ?: \"Failed to save image\")\n }\n }\n ExportAction.SHARE -> {\n val uriResult = ImageExportUtil.saveBitmapLocally(context, bitmapResult.data, filename)\n when (uriResult) {\n is Result.Success -> {\n ImageExportUtil.shareBitmap(context, uriResult.data)\n ExportResult.Success(null) // No URI needed for share action\n }\n is Result.Error -> ExportResult.Error(uriResult.message ?: \"Failed to create shareable image\")\n }\n }\n }\n }\n }\n } catch (e: Exception) {\n ExportResult.Error(e.message ?: \"Unknown error occurred\")\n }\n }\n}\n\n@Composable\nfun SunnahCardWithContainer(\n sunnah: Sunnah,\n backgroundColor: Color\n) {\n Box(\n modifier = Modifier\n .fillMaxSize()\n .background(backgroundColor)\n ) {\n SunnahFullCard(\n sunnah = sunnah,\n modifier = Modifier.fillMaxSize()\n )\n }\n}\n\ndata class ExportParams(\n val sunnah: Sunnah,\n val action: ExportAction\n)\n\nenum class ExportAction {\n SAVE,\n SHARE\n}\n\nsealed class ExportResult {\n data class Success(val uri: android.net.Uri?) : ExportResult()\n data class Error(val message: String) : ExportResult()\n}"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"call_69v1ia1e3","content":"The apply model made the following changes to the file:

