 }
 }

 /**
 * Wait for the ComposeView to be properly laid out
 */
 private suspend fun ComposeView.waitForLayout(): Unit = kotlinx.coroutines.suspendCancellableCoroutine { continuation ->
 if (isLaidOut) {
 continuation.resume(Unit) {}
 } else {
 addOnLayoutChangeListener(object : View.OnLayoutChangeListener {
 override fun onLayoutChange(
 v: View?,
 left: Int,
 top: Int,
 right: Int,
 bottom: Int,
 oldLeft: Int,
 oldTop: Int,
 oldRight: Int,
 oldBottom: Int
 ) {
 removeOnLayoutChangeListener(this)
 continuation.resume(Unit) {}
 }
 })
 }
 }

